messages.content:
{
  "early_commentary": {
    "label": "劉孝標注",
    "notes": [
      {
        "ref": "L01",
        "text": "(引殷浩爲揚州欲以抗/續晉陽秋曰簡文輔政)"
      },
      {
        "ref": "L02",
        "text": "(未之憚也/桓桓素輕浩)"
      }
    ]
  },
  "frozen_questions": [
    {
      "gap": "缺少正确断句，可能被误读为“殷侯既废桓公”，导致行动主体颠倒",
      "question_id": "Q1",
      "story_span": "殷侯既廢桓公語諸人曰"
    },
    {
      "gap": "缺少“淵源”即殷侯（殷浩）的字，否则会误以为另一人",
      "question_id": "Q2",
      "story_span": "少時與淵源共騎竹馬"
    },
    {
      "gap": "缺少“巳”应理解为“己”（自己，指桓温）的说明，否则可能误为“已”",
      "question_id": "Q3",
      "story_span": "巳輒取之"
    }
  ],
  "later_commentary": {
    "label": "余嘉錫箋疏",
    "notes": []
  },
  "primary_text": {
    "label": "世說新語正文",
    "text": "殷侯既廢桓公語諸人曰少時與淵源共騎竹馬我\n棄去巳輒取之故當出我下"
  },
  "story_id": "09-pinzao-038"
}
